const replyRefusal=(e:unknown)=>e instanceof Error&&e.message===PROJECT_REPLY_ERROR;
async function specialistFixture(transform:(content:string,call:number)=>string=(content)=>content,grantLimits:TestGrantLimits={}){
 let authorInput:unknown;const f=await contextWireFixture((body,call)=>{const payload=JSON.parse(JSON.parse(body).messages[1].content);const content=call===1?JSON.stringify(authorInput):JSON.stringify({version:1,taskId:payload.task.id,proposalDigest:payload.proposal.digest,decision:'ready',findings:[],unverifiedAreas:['Runtime tests and unseen source are not verified.']});return transform(content,call);},grantLimits);authorInput=f.patch();
 const wire=createContextBoundProjectTransport(f.options),packet=(role:'author'|'security'|'reviewer'|'tester',changes?:Awaited<ReturnType<typeof prepareProjectReplyChanges>>)=>prepareProjectModelContext(f.plan,f.taskId,f.snapshot,{role,model,selections:[range(f,role==='author'?'value = 1':'value = 2',role==='author'?'base':'proposed')],...(changes?{changes}:{})});
 const author=async()=>wire.request(await packet('author'));
 const proposal=async()=>{const reply=await author();return{reply,changes:await prepareProjectReplyChanges(reply)};};
 return{...f,wire,packet,author,proposal};
}
