 const f=await correctionAttemptFixture();try{const admission=await f.session().prepareCorrection(f.ticket),wire=createContextBoundProjectTransport({...f.wireOptions,admission,timing:{now:()=>0,wait:async()=>{f.revokeApproval();}}});await assert.rejects(()=>wire.request(f.packet),contextRefusal);assert.equal(f.correctionCalls(),0);assert.equal((await f.controller.inspect()).used.requests,2);}finally{f.cleanup();}
