test('uncertain checkpoint after correction reservation prevents HTTP and retains the reservation',async()=>{
 const f=await correctionAttemptFixture();try{const wire=createContextBoundProjectTransport({...f.wireOptions,admission:await f.session().prepareCorrection(f.ticket),checkpoint:async()=>{throw Error('PRIVATE_CHECKPOINT_ERROR');}});await assert.rejects(()=>wire.request(f.packet),contextRefusal);assert.equal(f.correctionCalls(),0);assert.equal((await f.controller.inspect()).used.requests,3);assert.equal(wire.snapshot().stopped,true);}finally{f.cleanup();}
});
